/**
 * #816: the registry-derived route tables (TECH_PLAN §16, rate-limits.md)
 * are regenerated by `npm run gen:route-docs`, and `tools/verify-local.sh`
 * runs that BEFORE the tests so parallel route-adding merges don't leave a
 * PR red. The conformance test (unchanged) still fails CI on a stale commit.
 */
import { describe, expect, it } from 'vitest';
import { existsSync, readFileSync } from 'node:fs';
import { join } from 'node:path';

const API_ROOT = join(__dirname, '..');
const REPO_ROOT = join(API_ROOT, '..', '..');

const readJson = (p: string) => JSON.parse(readFileSync(p, 'utf8')) as { scripts: Record<string, string> };

describe('route-docs regeneration wiring (#816)', () => {
  it('apps/api gen:route-docs runs both table generators', () => {
    const script = readJson(join(API_ROOT, 'package.json')).scripts['gen:route-docs'];
    expect(script).toBeDefined();
    for (const tool of ['tools/insert-registry-table.mts', 'tools/insert-rate-limit-table.mts']) {
      expect(script).toContain(tool);
      expect(existsSync(join(API_ROOT, tool)), `${tool} exists`).toBe(true);
    }
  });

  it('root gen:route-docs delegates to the api workspace', () => {
    const script = readJson(join(REPO_ROOT, 'package.json')).scripts['gen:route-docs'];
    expect(script).toMatch(/gen:route-docs.*--workspace @feasly\/api/);
  });

  it('verify-local.sh regenerates the tables before running the tests', () => {
    const sh = readFileSync(join(REPO_ROOT, 'tools', 'verify-local.sh'), 'utf8');
    const regen = sh.indexOf('step "regenerate route tables" npm run -s gen:route-docs');
    const tests = sh.indexOf('step "tests (all workspaces)"');
    expect(regen, 'regen step present').toBeGreaterThan(-1);
    expect(tests, 'tests step present').toBeGreaterThan(-1);
    expect(regen).toBeLessThan(tests);
  });
});
